#import "QuietUI.h"
#define main DDLApplicationMain
#import "../Sources/App.m"
#undef main
#import "../Sources/SSCourseWindow.m"
static NSUInteger checks;
static void Check(BOOL ok,NSString *why){checks++;if(!ok){fprintf(stderr,"FAIL: %s\n",why.UTF8String);exit(1);}}
static void Wait(BOOL(^ready)(void)){NSDate *end=[NSDate dateWithTimeIntervalSinceNow:8];while(!ready() && end.timeIntervalSinceNow>0)[NSRunLoop.mainRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.01]];Check(ready(),@"bounded submission check completes");}
int main(){@autoreleasepool{
 [NSApplication sharedApplication];[NSApp setActivationPolicy:NSApplicationActivationPolicyProhibited];NSDictionary *course=@{@"fork":@"student/selection",@"branch":@"main",@"path":NSProcessInfo.processInfo.environment[@"AM_TEST_DATA"]};NSArray *changes=@[@{@"path":@"a.md",@"status":@"M"},@{@"path":@"b.md",@"status":@"??"},@{@"path":@".env",@"status":@"??",@"sensitive":@YES}];SSSubmissionController *sheet=[[SSSubmissionController alloc] initWithCourse:course changes:changes];NSWindow *host=[[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,1050,800) styleMask:NSWindowStyleMaskTitled backing:NSBackingStoreBuffered defer:NO];[host beginSheet:sheet.window completionHandler:nil];sheet.message.stringValue=@"Synthetic selection";
 [sheet.selectAllFilesButton performClick:nil];Check([[sheet chosenPaths] isEqual:@[@"a.md",@"b.md"]] && sheet.checks[2].state==NSControlStateValueOff && [sheet.selectAllFilesButton.title isEqual:@"取消全选"],@"select all includes every eligible file and never enables an excluded file");[sheet.selectAllFilesButton performClick:nil];Check([sheet chosenPaths].count==0 && [sheet.selectAllFilesButton.title isEqual:@"全选"],@"same control can clear selection");[sheet.checks[0] performClick:nil];[sheet.selectAllFilesButton performClick:nil];Check([sheet chosenPaths].count==2,@"partial selection is completed by select all");
 __block NSString *text=@"# Synthetic answer\n1 + 1 = 2\n";__block NSUInteger submits=0;sheet.performCheck=^NSDictionary *(NSArray *paths,NSArray *ids,NSString *extra,NSMutableDictionary *cache,BOOL(^cancelled)(void),NSError **error){NSData *bytes=[text dataUsingEncoding:NSUTF8StringEncoding];NSString *version=AMPreflightHash(bytes);NSDictionary *snapshot=@{@"paths":paths,@"files":@{@"a.md":@{@"text":text,@"version":version},@"b.md":@{@"text":@"Synthetic appendix",@"version":@"appendix"}},@"version":version,@"head":@"synthetic",@"repository":course[@"fork"],@"branch":@"main"};return @{@"snapshot":snapshot,@"requirements":@"Synthetic question",@"report":AMPreflightCheck(snapshot,@"Synthetic question",cache,cancelled)};};sheet.submit=^(NSArray *paths,NSString *message){submits++;};[sheet save:nil];Wait(^BOOL{return !sheet.checking && sheet.report!=nil;});Check(sheet.documentPreview.renderedOnly && [[sheet.documentPreview valueForKey:@"mode"] isHidden],@"report has no source switch");[sheet.documentPreview showSource:YES];Check(![[sheet.documentPreview valueForKey:@"web"] isHidden],@"report remains rendered even if an old source action is invoked");
 NSMutableDictionary *materials=sheet.snapshot.mutableCopy;materials[@"reviewRequirements"]=@"Synthetic question with matching source";materials[@"questionLinks"]=@{@"question":@{@"answer":@"a.md"}};sheet.reviewMaterialsSnapshot=materials;[sheet bindReviewMaterials];NSString *bound=sheet.report[@"version"];Check(![bound isEqual:sheet.report[@"reviewBaseVersion"]],@"fixture reproduces a report with material-bound identity");sheet.acknowledge.state=NSControlStateValueOn;[sheet.primary performClick:nil];Wait(^BOOL{return submits==1 || !sheet.checking;});Check(submits==1 && sheet.closed,@"unchanged answer and linked materials submit once instead of repeating false modification warnings");
 SSSubmissionController *changed=[[SSSubmissionController alloc] initWithCourse:course changes:changes];[host beginSheet:changed.window completionHandler:nil];changed.message.stringValue=@"Keep actual change protection";[changed.selectAllFilesButton performClick:nil];changed.performCheck=sheet.performCheck;changed.submit=sheet.submit;[changed save:nil];Wait(^BOOL{return !changed.checking && changed.report!=nil;});text=@"# Synthetic answer\n1 + 1 = 3\n";changed.acknowledge.state=NSControlStateValueOn;[changed.primary performClick:nil];Wait(^BOOL{return !changed.checking;});Check(submits==1 && [changed.validation.stringValue containsString:@"变化"] && changed.acknowledge.state==NSControlStateValueOff,@"real file changes still require reviewing the new report");changed.acknowledge.state=NSControlStateValueOn;[changed.primary performClick:nil];Wait(^BOOL{return submits==2;});Check(changed.closed,@"reviewed changed files can submit on the next explicit action");[host orderOut:nil];printf("PASS: %lu file selection, rendered report and final version assertions\n",(unsigned long)checks);
}return 0;}
